"""Actual screen search and exact source-language copying, not a human outcome study."""
import json,functools,http.server,threading,hashlib
from pathlib import Path
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1];out=R/'research/ui-v38';out.mkdir(exist_ok=True);checks=[];errors=[]
def check(n,v):assert v,n;checks.append(n)
x=json.loads((R/'dist/data/english-screen-library-v38.json').read_text());base=json.loads((R/'dist/data/user-capture-intake-v37.json').read_text());b={r['id']:r for r in base['records']};check('ten unchanged safe original captures and literal English headings',len(x['screens'])==10 and all(r['native_title']==b[r['id']]['observed_labels'][0] and r['observed_labels']==b[r['id']]['observed_labels'] and hashlib.sha256((R/'dist'/r['image_path']).read_bytes()).hexdigest()==r['image_sha256'] for r in x['screens']))
class Quiet(http.server.SimpleHTTPRequestHandler):
 def log_message(self,*a):pass
s=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Quiet,directory=str(R/'dist')));threading.Thread(target=s.serve_forever,daemon=True).start();url='http://127.0.0.1:'+str(s.server_port)
try:
 with sync_playwright() as p:
  browser=p.chromium.launch(headless=True,args=['--no-sandbox']);context=browser.new_context(viewport={'width':1440,'height':1000});context.grant_permissions(['clipboard-read','clipboard-write']);page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
  page.goto(url+'/#explore?q=계좌발급');page.locator('#practitioner-case-results .practitioner-reference-card').first.wait_for();check('account keyword directly shows official account-opening images',page.locator('#practitioner-case-results .bank-guide-image').count()>=2);check('primary case cards precede work-definition list',page.locator('#practitioner-case-results').evaluate('(e)=>e.getBoundingClientRect().top')<page.locator('#task-results').evaluate('(e)=>e.getBoundingClientRect().top'));page.screenshot(path=str(out/'account-keyword-desktop.png'))
  page.locator('#practitioner-case-results').get_by_role('link',name='화면 보기',exact=True).first.click();page.locator('#content .bank-guide-image').first.wait_for();check('actual guide image and source available without country-selection gate',page.locator('#bank-country').count()==0 and page.get_by_role('link',name='서비스·공식 원문 열기').count()==1);page.get_by_role('link',name='검색 결과로 돌아가기').click();page.locator('#task-query').wait_for();check('source-reference return retains keyword',page.locator('#task-query').input_value()=='계좌발급')
  page.goto(url+'/#explore?q=회원가입');page.locator('.bank-task').wait_for();check('signup search reaches digital service creation definition without rewriting canonical ids','WGSS-UI-F7B2CD2DC28C' in page.locator('.bank-task').first.get_attribute('href'))
  page.goto(url+'/#screen-library?q=Passkeys');page.locator('.english-screen-card').wait_for();check('English original search finds one actual security screenshot without country',page.locator('.english-screen-card').count()==1 and page.locator('#bank-country,#filter-market').count()==0);page.locator('.english-screen-card').get_by_role('link',name='화면·영어 문구 보기').click();page.locator('[data-copy-observed-label]').first.wait_for();check('native heading displayed as original English',page.locator('h1').inner_text()=='Password');page.locator('[data-copy-observed-label="Passkeys"]').click();page.wait_for_function("document.querySelector('#english-copy-status').textContent.includes('복사했습니다')");check('clipboard receives exact observed wording',page.evaluate('navigator.clipboard.readText()')=='Passkeys')
  page.locator('#content').get_by_role('link',name='검색 결과로 돌아가기',exact=True).click();page.locator('.english-screen-card').wait_for();check('English library return preserves original query',page.url.endswith('#screen-library?q=Passkeys'))
  page.goto(url+'/#screen-library?q=Permissions');page.locator('.english-screen-card').wait_for();page.locator('.english-screen-card').get_by_role('link',name='화면·영어 문구 보기').click();page.locator('[data-copy-observed-label]').first.click();page.wait_for_function("document.querySelector('#english-copy-status').textContent.includes('복사했습니다')");check('apostrophe copied literally without HTML encoding or translation',page.evaluate('navigator.clipboard.readText()')=="Permissions you've given")
  page.goto(url+'/#screen-library?group=documents&q=statement');page.locator('.english-screen-card').first.wait_for();check('task/language browse produces two document-stage screenshots',page.locator('.english-screen-card').count()==2 and page.locator('#english-screen-group').input_value()=='documents');u=page.url;page.reload();page.locator('.english-screen-card').first.wait_for();check('library filters and query survive refresh',page.url==u and page.locator('#english-screen-query').input_value()=='statement')
  page.set_viewport_size({'width':390,'height':844});check('English library mobile fits viewport',page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'));page.screenshot(path=str(out/'english-library-mobile.png'))
  page.goto(url+'/#explore?q=계좌발급');page.locator('#practitioner-case-results .practitioner-reference-card').first.wait_for();check('direct case results fit mobile',page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'));page.screenshot(path=str(out/'account-keyword-mobile.png'))
  check('no browser exceptions',not errors);browser.close()
 print(json.dumps({'browser_practitioner_v38':'passed','checks':len(checks),'items':checks},ensure_ascii=False))
finally:s.shutdown();s.server_close()
